AR_TATWEEL = "ـ"
def norm_ar(s):
    return ' '.join(str(s).replace(AR_TATWEEL, '').split())
AR_EN_NORM = {norm_ar(k): v for k, v in AR_EN.items()}
EN_AR_NORM = {norm(k): v for k, v in EN_AR.items()}
EN_AR_PARTS_NORM = [(norm(k), v) for k, v in EN_AR_PARTS]
EN_AR_GENERIC_NORM = [(norm(k), v) for k, v in EN_AR_GENERIC]
PLACES_NORM = [(norm(k), v) for k, v in PLACES]

def _apply_parts(s, parts):
    for src, tgt in sorted(parts, key=lambda p: -len(p[0])):
        if src and src in s:
            s = s.replace(src, tgt)
    return s

def _units_en_ar(s):
    s = re.sub(r'(\d+(?:\.\d+)?)\s*(?:kva|KVA|Kva)\b', r'\1 ك.ف.أ', s)
    s = re.sub(r'(\d+(?:\.\d+)?)\s*MVA\b', r'\1 م.ف.أ', s)
    s = re.sub(r'(\d+(?:\.\d+)?)\s*(?:kv|KV|kV|Kv)\b', r'\1 ك.ف', s)
    s = re.sub(r'(\d+(?:\.\d+)?)\s*volt\b', r'\1 فولت', s)
    s = re.sub(r'(\d+(?:\.\d+)?)\s*Vdc\b', r'\1 فولت تيار مستمر', s)
    s = re.sub(r'(\d+(?:\.\d+)?)\s*Vac\b', r'\1 فولت تيار متردد', s)
    s = re.sub(r'(\d+(?:\.\d+)?)\s*mm2\b', r'\1 مم2', s)
    s = re.sub(r'(\d+(?:\.\d+)?)\s*mm\b', r'\1 مم', s)
    s = re.sub(r'(\d+(?:\.\d+)?)\s*HP\b', r'\1 حصان', s)
    return s

def translate_ar(s):
    """Arabic -> English. Returns (translated, leftover_arabic_bool)."""
    if not s or not s.strip():
        return s, False
    n = norm_ar(s)
    if n in AR_EN_NORM:
        return AR_EN_NORM[n], False
    # segment on '|' (text-field rows) and translate segment by segment
    if '|' in n:
        parts = [translate_ar(p)[0] for p in n.split('|')]
        out = ' | '.join(parts)
        return out, bool(re.search(r'[\u0600-\u06FF]', out))
    # fallback: phrase parts (months, status words)
    out = n
    for src, tgt in [("معتمد", "Approved"), ("أغسطس", "August"), ("مارس", "March"),
                     ("فبراير", "February"), ("ديسمبر", "December"), ("مايو", "May"),
                     ("يناير", "January"), ("يونيو", "June"), ("يوليو", "July"),
                     ("سبتمبر", "September"), ("أكتوبر", "October"), ("نوفمبر", "November")]:
        out = out.replace(src, tgt)
    return out, bool(re.search(r'[\u0600-\u06FF]', out))

def translate_en(s):
    """English -> Arabic. Returns (translated, leftover_latin_words list)."""
    if not s or not s.strip():
        return s, []
    n = norm(s)
    if n in EN_AR_NORM:
        return EN_AR_NORM[n], []
    if n in EN_TITLES:
        return EN_TITLES[n], []
    if '|' in n:
        parts = [translate_en(p)[0] for p in n.split('|')]
        out = ' | '.join(parts)
        return out, _leftover_latin(out)
    out = _apply_parts(n, EN_AR_PARTS_NORM)
    out = _apply_parts(out, EN_AR_GENERIC_NORM)
    out = _apply_parts(out, PLACES_NORM)
    out = _units_en_ar(out)
    return out, _leftover_latin(out)

