def _leftover_latin(s):
    words = re.findall(r'[A-Za-z][A-Za-z0-9\-/\.]*', s)
    bad = []
    for w in words:
        base = w.strip('.,;:)(')
        if base in ALLOWED_LATIN:
            continue
        if re.fullmatch(r'[A-Z]{1,3}-?\d+[A-Za-z0-9\-/]*', base):  # codes like 3P72, 8D4, 7UT512
            continue
        if re.fullmatch(r'\d+[A-Za-z]+', base):  # model fragments like 2M12
            continue
        if re.fullmatch(r'[A-Z]\d+', base):
            continue
        if re.fullmatch(r'(Y|M|D|I|W|SC|P|T|R|S|F|H|C|B|A|E|G|K|L|N|O|Q|U|V|X|J)\d+(:\d+)?', base):
            continue
        if re.fullmatch(r'[A-Z][a-z]+[A-Z][A-Za-z0-9]*', base):  # CamelCase model names
            continue
        bad.append(base)
    return bad
